-- ------------------------------------------------------------
-- 7. 확인용 / 확인용
-- ------------------------------------------------------------
SELECT BUSINESS_PARTNER_ID, PARTNER_CODE, PARTNER_NAME FROM TB_BUSINESS_PARTNER WHERE BUSINESS_PARTNER_ID BETWEEN 1 AND 15 ORDER BY BUSINESS_PARTNER_ID;
SELECT WAREHOUSE_ID, WAREHOUSE_CODE, WAREHOUSE_NAME, WAREHOUSE_TYPE FROM TB_WAREHOUSE WHERE WAREHOUSE_ID BETWEEN 1 AND 15 ORDER BY WAREHOUSE_ID;
SELECT ITEM_ID, ITEM_CODE, ITEM_NAME, ITEM_TYPE, BARCODE FROM TB_ITEM WHERE ITEM_ID BETWEEN 1 AND 15 ORDER BY ITEM_ID;
SELECT COUNT(*) AS ITEM_PRICE_COUNT FROM TB_ITEM_PRICE WHERE ITEM_ID BETWEEN 1 AND 15;
SELECT COUNT(*) AS INVENTORY_COUNT FROM TB_INVENTORY WHERE WAREHOUSE_ID BETWEEN 1 AND 15;


-- ------------------------------------------------------------
-- 8. シーケンス同期 / 시퀀스 동기화
-- 더미 PK의 최댓값을 현재값으로 맞춰 다음 등록이 MAX(PK)+1이 되도록 합니다.
-- ------------------------------------------------------------
DECLARE
  v_current NUMBER;
  v_target NUMBER;
  v_delta NUMBER;
  PROCEDURE sync_seq(p_seq VARCHAR2, p_table VARCHAR2, p_col VARCHAR2) IS
  BEGIN
    EXECUTE IMMEDIATE 'SELECT NVL(MAX(' || p_col || '), 0) FROM ' || p_table INTO v_target;
    IF v_target < 1 THEN RETURN; END IF;
    EXECUTE IMMEDIATE 'SELECT ' || p_seq || '.NEXTVAL FROM dual' INTO v_current;
    IF v_current <> v_target THEN
      v_delta := v_target - v_current;
      EXECUTE IMMEDIATE 'ALTER SEQUENCE ' || p_seq || ' INCREMENT BY ' || TO_CHAR(v_delta, 'FM99999999999999999990');
      EXECUTE IMMEDIATE 'SELECT ' || p_seq || '.NEXTVAL FROM dual' INTO v_current;
      EXECUTE IMMEDIATE 'ALTER SEQUENCE ' || p_seq || ' INCREMENT BY 1';
    END IF;
  END;
BEGIN
  sync_seq('TB_MANAGER_SEQ', 'TB_MANAGER', 'MANAGER_ID');
  sync_seq('TB_PARTNER_GROUP_SEQ', 'TB_PARTNER_GROUP', 'PARTNER_GROUP_ID');
  sync_seq('TB_WAREHOUSE_GROUP_SEQ', 'TB_WAREHOUSE_GROUP', 'WAREHOUSE_GROUP_ID');
  sync_seq('TB_ITEM_GROUP_SEQ', 'TB_ITEM_GROUP', 'ITEM_GROUP_ID');
  sync_seq('TB_PROD_PROCESS_SEQ', 'TB_PROD_PROCESS', 'PROD_PROCESS_ID');
  sync_seq('TB_QUALITY_INSP_TYPE_SEQ', 'TB_QUALITY_INSP_TYPE', 'QUALITY_INSP_TYPE_ID');
  sync_seq('TB_BUSINESS_PARTNER_SEQ', 'TB_BUSINESS_PARTNER', 'BUSINESS_PARTNER_ID');
  sync_seq('TB_WAREHOUSE_SEQ', 'TB_WAREHOUSE', 'WAREHOUSE_ID');
  sync_seq('TB_ITEM_SEQ', 'TB_ITEM', 'ITEM_ID');
  sync_seq('TB_ITEM_PRICE_SEQ', 'TB_ITEM_PRICE', 'ITEM_PRICE_ID');
END;
/
